from __future__ import annotations

import hashlib
import random
from dataclasses import dataclass


@dataclass(frozen=True)
class ReviewQuestion:
    id: str
    topic: str
    prompt: str
    choices: tuple[str, ...]
    correct: tuple[int, ...]
    explanation: str
    memory_hook: str
    images: tuple[str, ...] = ()
    image_choices: bool = False


def q(number, topic, prompt, choices, correct, explanation, hook, images=(), image_choices=False):
    return ReviewQuestion(f"kh-{number:02d}", topic, prompt, tuple(choices), tuple(correct), explanation, hook, tuple(images), image_choices)


