QUESTIONS_BY_ID = {item.id: item for item in KHASHAN_QUESTIONS}


def shuffled_questions(seed: int) -> tuple[ReviewQuestion, ...]:
    items = list(KHASHAN_QUESTIONS)
    random.Random(seed).shuffle(items)
    return tuple(items)


def shuffled_choice_indexes(question: ReviewQuestion, seed: int) -> tuple[int, ...]:
    digest = hashlib.sha256(f"{seed}:{question.id}".encode()).digest()
    indexes = list(range(len(question.choices)))
    random.Random(int.from_bytes(digest[:8], "big")).shuffle(indexes)
    return tuple(indexes)
